  const BORDER = [[66, 69.5], [66, 68.5], [64, 67], [60, 65], [59.5, 62], [59.5, 60], [59, 57], [59, 55], [59, 53.4], [58.6, 51.2], [55.1, 51.8], [51.4, 51.2], [51.3, 49.5], [51.9, 47.1], [49.5, 46.2], [47.6, 44.5], [47.8, 43], [49.3, 41.2], [47, 42], [44.5, 42.7], [42.5, 43.2], [40, 43.5], [37.6, 44.8], [34, 43.6], [29.1, 41.2], [26.5, 40.3], [26.1, 39.5]];
  const EUROPE_CLIP = [[-45, 87], [70, 87], ...BORDER, [25.5, 36], [20, 28], [-45, 28]];
